contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // Drive the contract: caller (this contract) will call Put with an arbitrary small deposit.
    // We require the caller has enough ETH to send 'amt'.
    // The property asserts that after calling Put with amt < c.MinSum(), the recorded Acc balance for this contract equals amt.
    function runTest(uint amt) public payable {
        // precondition: amt is a positive deposit smaller than MinSum
        require(amt > 0, "amt must be > 0");
        uint min = c.MinSum();
        require(amt < min, "amt must be < MinSum");
        require(address(this).balance >= amt, "contract lacks funds to send amt");

        // action: call Put with amt value
        c.Put{value: amt}(0);

        // observe: Acc[address(this)].balance is public getter Acc
        // assert that small deposit was accepted and recorded as balance
        assert(c.Acc(address(this)).balance == amt);
    }

    // allow the test contract to receive ETH so it can forward it in runTest
    receive() external payable {}
}

