pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // fuzz params: actor address and candidate unlockTime
    function testFuzz_property(address actor, uint256 candidateUnlockTime, uint256 sendAmt) public {
        // keep sendAmt reasonable (but allow zero as well)
        sendAmt = bound(sendAmt, 0, 10 ether);
        // actor must not be zero address for vm.prank to be meaningful
        vm.assume(actor != address(0));

        // fund actor so they can send
        vm.deal(actor, sendAmt);

        // advance time arbitrarily to exercise block.timestamp interactions
        // allow fuzz to control time via vm.warp but keep wide bounds
        uint256 warpTo = uint256(uint160(actor)) % 100000; // derive some varied warp from actor
        vm.warp(block.timestamp + warpTo);

        // perform Put as the actor with fuzzed candidateUnlockTime and fuzzed value
        vm.prank(actor);
        bool ok;
        try c.Put{value: sendAmt}(candidateUnlockTime) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule (single assertion): if the Put call returned (did not revert), then
        // the stored unlockTime for actor is >= current block.timestamp. The reference
        // implementation always enforces acc.unlockTime = max(_unlockTime, block.timestamp).
        // The mutant that uses min(...) can violate this rule for some inputs; the fuzzer
        // will find such inputs where ok==true but unlockTime < block.timestamp.
        if (ok) {
            // read the public mapping Acc(actor).unlockTime via the autogenerated getter
            // The mapping returns a struct; solidity exposes members as separate getters
            uint stored = c.Acc(actor).unlockTime;
            assertTrue(stored >= block.timestamp);
        } else {
            // If the call reverted, nothing is required; we only assert on successful Put
            assertTrue(true);
        }
    }
}

