contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    // Fuzzed params: an actor address and an amount to send
    function testFuzz_property(address actor, uint256 amount) public {
        // keep amount in a sensible wide range (0..1 ether*100)
        amount = bound(amount, 0, 100 ether);
        // We only consider calls that send > 0 wei, because Put with 0 value doesn't append meaningful Value in Log
        vm.assume(amount > 0);
        // Fund the actor so it can send
        vm.deal(actor, amount);
        // Call Put from actor sending `amount`
        vm.prank(actor);
        // perform the payable call; use try/catch to detect reverts (not expected)
        bool ok;
        try c.Put{value: amount}(block.timestamp + 1) {
            ok = true;
        } catch {
            ok = false;
        }
        // If the Put call reverted, there's no guarantee about logs; require success for the property
        vm.assume(ok);

        // Now read the Log History length via the public getter on Log contract stored at c.LogFile()
        // The C contract's LogFile is public in the provided reference; however if it's not accessible by name,
        // we can read the Log contract at the address passed in setup (address(this)) and query History
        // The reference test setup used address(this) as the Log contract, so History should have grown by 1
        // We assert that the Log (this) saw at least one message with matching sender and value as the last entry.

        // Access the Log contract that C references by calling the public getter LogFile() if available.
        // Fallback: we know in setUp we passed address(this) so the History is on this contract.

        // The Log contract in the original source has: Message[] public History; so a getter History(uint)-> returns (Sender,Data,Val,Time)
        // We'll read the last index by querying length via trying increasing indices is not possible; but the auto getter for History has a length via History(uint)
        // However solidity auto getter doesn't provide length; instead, we can rely on the fact that our test contract (this) served as the Log and we can implement compatible interface below.

        // Cast address(this) to LogLike to read last message
        LogLike log = LogLike(address(this));
        (address lastSender, , uint256 lastVal, ) = log.History(log.HistoryLength() - 1);

        // The universal property: after a successful Put sending amount, the last History entry's Sender == actor and Val == amount
        assertTrue(lastSender == actor && lastVal == amount);
    }
}

// Minimal interface matching the provided Log contract's getters that our test uses.
contract LogLike {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    // auto-generated getter for History(uint) -> (address,string,uint,uint)
    function History(uint) public view returns (address, string memory, uint, uint) {}
    // The original Log did not define HistoryLength(), so we add a helper in our test contract (this) to expose length.
    // To satisfy the call above, we implement it here in this contract because address(this) is the Log used by C in setUp.
    function HistoryLength() public view returns (uint) {}
}

// Implement the Log contract behaviour on this test contract so that C can call AddMessage on it.
// We implement only what's needed: AddMessage and storage for History and a helper to expose length.
contract Test is LogLike {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public override History;
    Message LastMsg;

    function AddMessage(address _adr,uint _val, string memory _data) public override {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }

    // Provide the auto getter signatures
    function History(uint i) public view override returns (address, string memory, uint, uint) {
        Message storage m = History[i];
        return (m.Sender, m.Data, m.Val, m.Time);
    }
    function HistoryLength() public view override returns (uint) { return History.length; }
}

