        (uint accUnlock, uint accBal) = (c.Acc(address(this)).unlockTime, c.Acc(address(this)).balance);

        // Preconditions to reach the deciding state: recorded balance >= MinSum and >= collectAmt
        require(accBal >= c.MinSum(), "recorded balance < MinSum");
        require(accBal >= collectAmt, "recorded balance < collectAmt");

        // We will attempt to Collect exactly at time == accUnlock by calling Collect immediately
        // (the stored unlockTime is an observable value accUnlock)
        c.Collect(collectAmt);

