        // On the original contract P, collection is only allowed strictly after unlockTime, so balance must remain unchanged.
        // On mutant M (>=) it would allow collection at exact unlock time and reduce the stored balance by collectAmt.
        // Assert that the stored balance is NOT reduced (i.e., still equals accBal).
        assert(c.Acc(address(this)).balance == accBal);
    }

